import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBan";
import type { IPageIDiscussionBoardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardBan";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E test for listing discussion board bans with various filters and pagination by a moderator or administrator. 
 *
 * This test covers the following business scenarios:
 * 1. Data setup: Create multiple member accounts (moderator, regular members) and several ban records with varied attributes (permanent/temp, different members, reasons, expirations).
 * 2. Tests retrieval of ban list with:
 *    a. No filters (should return all with correct pagination)
 *    b. member_id filter (should return only bans for that member)
 *    c. moderator_id filter (should return only bans by that moderator)
 *    d. permanent (true/false) filter (must reflect only permanent or only temporary bans)
 *    e. filter cases which return no rows (nonexistent member_id)
 *    f. Pagination (limit testing)
 * 3. Access: Only moderators (=set up in test) should have access, but there is no separate privilege API; just regular creation.
 *
 * At each step, result type correctness and business rule effect are asserted.
 */
export async function test_api_discussionBoard_test_list_bans_with_various_filters_and_pagination(
  connection: api.IConnection,
) {
  // 1. Data setup: Create moderator & members
  const moderator = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    },
  });
  typia.assert(moderator);

  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    },
  });
  typia.assert(member1);

  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    },
  });
  typia.assert(member2);

  // 2. Create several ban records: permanent and temporary
  const permBan = await api.functional.discussionBoard.bans.post(connection, {
    body: {
      member_id: member1.id,
      moderator_id: moderator.id,
      ban_reason: "Multiple TOS violation",
      permanent: true,
      expires_at: null,
    },
  });
  typia.assert(permBan);

  const tempBan = await api.functional.discussionBoard.bans.post(connection, {
    body: {
      member_id: member2.id,
      moderator_id: moderator.id,
      ban_reason: "Spam",
      permanent: false,
      expires_at: new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
    },
  });
  typia.assert(tempBan);

  // 3a. List bans with no filters: should include both bans
  const allBans = await api.functional.discussionBoard.bans.patch(connection, {
    body: {},
  });
  typia.assert(allBans);
  TestValidator.predicate("no filter: all setup bans are included")(!!allBans.data.find((b) => b.id === permBan.id) && !!allBans.data.find((b) => b.id === tempBan.id));

  // 3b. member_id filter
  const bansByMember1 = await api.functional.discussionBoard.bans.patch(connection, {
    body: { filter: { member_id: member1.id } },
  });
  typia.assert(bansByMember1);
  TestValidator.predicate("bans filtered for member1")(bansByMember1.data.every((b) => b.member_id === member1.id));

  // 3c. moderator_id filter
  const bansByModerator = await api.functional.discussionBoard.bans.patch(connection, {
    body: { filter: { moderator_id: moderator.id } },
  });
  typia.assert(bansByModerator);
  TestValidator.predicate("bans filtered for moderator")(bansByModerator.data.every((b) => b.moderator_id === moderator.id));

  // 3d. permanent true
  const onlyPermanent = await api.functional.discussionBoard.bans.patch(connection, {
    body: { filter: { permanent: true } },
  });
  typia.assert(onlyPermanent);
  TestValidator.predicate("permanent bans only")(onlyPermanent.data.every((b) => b.permanent === true));

  // 3d2. permanent false
  const onlyTemporary = await api.functional.discussionBoard.bans.patch(connection, {
    body: { filter: { permanent: false } },
  });
  typia.assert(onlyTemporary);
  TestValidator.predicate("temporary bans only")(onlyTemporary.data.every((b) => b.permanent === false));

  // 3e. Non-existent member_id (should return no data)
  const bansByNonexistent = await api.functional.discussionBoard.bans.patch(connection, {
    body: { filter: { member_id: typia.random<string & tags.Format<"uuid">>() } },
  });
  typia.assert(bansByNonexistent);
  TestValidator.equals("empty for non-existent member")(bansByNonexistent.data.length)(0);

  // 3f. Pagination test: limit = 1
  const oneBan = await api.functional.discussionBoard.bans.patch(connection, {
    body: { limit: 1 },
  });
  typia.assert(oneBan);
  TestValidator.equals("one record per page")(oneBan.data.length)(1);
  TestValidator.equals("pagination limit meta")(oneBan.pagination.limit)(1);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBan";

/**
 * Validate retrieval of ban details by ID as authorized user, with access control and error handling.
 *
 * 1. Create a discussion board member to be banned
 * 2. Create a moderator user (for simplicity, use the same API unless moderator creation endpoint exists)
 * 3. Issue a ban as moderator against the member
 * 4. Retrieve the ban details as moderator and check all returned fields
 * 5. Attempt to retrieve the ban details as unauthorized (non-moderator) user and verify access denied
 * 6. Attempt to retrieve non-existent ban, and expect a not found (404) error
 */
export async function test_api_discussionBoard_test_get_ban_details_by_id(
  connection: api.IConnection,
) {
  // 1. Create target member
  const targetMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: RandomGenerator.pick([
        undefined, null, typia.random<string & tags.Format<"uri">>(),
      ]),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(targetMember);

  // 2. Create moderator member (simulate moderator with a different user)
  const moderatorMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: RandomGenerator.pick([
        undefined, null, typia.random<string & tags.Format<"uri">>(),
      ]),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(moderatorMember);

  // 3. Moderator creates a ban against member
  const banCreateInput = {
    member_id: targetMember.id,
    moderator_id: moderatorMember.id,
    ban_reason: RandomGenerator.paragraph()(),
    permanent: RandomGenerator.pick([true, false]),
    expires_at: RandomGenerator.pick([
      null,
      new Date(Date.now() + 1000 * 60 * 60 * 24).toISOString(),
    ]),
  } satisfies IDiscussionBoardBan.ICreate;

  // For permanent ban, expires_at must be null
  if (banCreateInput.permanent) banCreateInput.expires_at = null;
  else if (!banCreateInput.expires_at)
    banCreateInput.expires_at = new Date(Date.now() + 1000 * 60 * 60 * 24 * 2).toISOString();

  const createdBan = await api.functional.discussionBoard.bans.post(connection, {
    body: banCreateInput,
  });
  typia.assert(createdBan);
  TestValidator.equals("ban.member_id")(createdBan.member_id)(targetMember.id);
  TestValidator.equals("ban.moderator_id")(createdBan.moderator_id)(moderatorMember.id);
  TestValidator.equals("ban.permanent")(createdBan.permanent)(banCreateInput.permanent);
  TestValidator.equals("ban.ban_reason")(createdBan.ban_reason)(banCreateInput.ban_reason);
  if (createdBan.permanent)
    TestValidator.equals("ban.expires_at for permanent")(createdBan.expires_at)(null);
  else
    TestValidator.equals("ban.expires_at")(createdBan.expires_at)(banCreateInput.expires_at);
  TestValidator.predicate("ban.created_at present")(!!createdBan.created_at);

  // 4. Retrieve ban as moderator
  const fetchedBan = await api.functional.discussionBoard.bans.getById(connection, {
    id: createdBan.id,
  });
  typia.assert(fetchedBan);
  TestValidator.equals("ban.id")(fetchedBan.id)(createdBan.id);
  TestValidator.equals("ban.member_id")(fetchedBan.member_id)(createdBan.member_id);
  TestValidator.equals("ban.moderator_id")(fetchedBan.moderator_id)(createdBan.moderator_id);
  TestValidator.equals("ban.ban_reason")(fetchedBan.ban_reason)(createdBan.ban_reason);
  TestValidator.equals("ban.permanent")(fetchedBan.permanent)(createdBan.permanent);
  TestValidator.equals("ban.expires_at")(fetchedBan.expires_at)(createdBan.expires_at);
  TestValidator.equals("ban.deleted_at")(fetchedBan.deleted_at)(createdBan.deleted_at ?? null);

  // 5. Retrieve ban as unauthorized user (new user)
  const unauthorizedUser = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: RandomGenerator.pick([
        undefined, null, typia.random<string & tags.Format<"uri">>(),
      ]),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(unauthorizedUser);

  // Access should be denied: since actual role-base authentication is not enforced in E2E context,
  // we expect TestValidator.error (simulate as needed)
  await TestValidator.error("unauthorized ban detail access should fail")(async () => {
    await api.functional.discussionBoard.bans.getById(connection, { id: createdBan.id });
  });

  // 6. Retrieve non-existent ban (random UUID)
  await TestValidator.error("Not found for non-existing ban")(async () => {
    await api.functional.discussionBoard.bans.getById(connection, {
      id: typia.random<string & tags.Format<"uuid">>(),
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBan";

/**
 * Test ban creation workflows and ensure correct enforcement of business/validation rules.
 *
 * This test verifies both successful and failure scenarios for banning members.
 * Ban records must be created properly (permanent and temporary), with required audit metadata,
 * and error handling must work for duplicate bans, non-existent targets, badly formed bans,
 * and privilege checks. Assumes all role information is referenced by member_id/moderator_id fields.
 *
 * **Workflow:**
 * 1. Register target member (ban subject)
 * 2. Register moderator/admin (ban authority)
 * 3. (Success) Moderator issues permanent ban on target; check data returned
 * 4. (Success) Issue a temporary ban (with expires_at in future) on a new target
 * 5. (Failure) Try to issue perm ban again (duplicate) – expect error
 * 6. (Failure) Ban a non-existent member – expect error
 * 7. (Failure) Temporary ban with past expires_at – validation error
 * 8. (Failure) Ban by unprivileged user (basic member as moderator) – forbidden
 */
export async function test_api_discussionBoard_test_create_ban_with_required_and_optional_fields(
  connection: api.IConnection,
) {
  // 1. Register a member to be the ban target
  const targetMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      // optional profile_image_url omitted
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(targetMember);

  // 2. Register a member to act as moderator/admin
  const moderatorMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(moderatorMember);

  // 3. (Success) Issue a permanent ban
  const banReason = "Test permanent ban: automated e2e scenario";
  const permBan = await api.functional.discussionBoard.bans.post(connection, {
    body: {
      member_id: targetMember.id,
      moderator_id: moderatorMember.id,
      ban_reason: banReason,
      permanent: true,
      // expires_at omitted for permanent ban
    } satisfies IDiscussionBoardBan.ICreate,
  });
  typia.assert(permBan);
  // Structure validation
  TestValidator.equals("ban is permanent")(permBan.permanent)(true);
  TestValidator.equals("correct member")(permBan.member_id)(targetMember.id);
  TestValidator.equals("correct moderator")(permBan.moderator_id)(moderatorMember.id);
  TestValidator.equals("ban reason matches")(permBan.ban_reason)(banReason);
  TestValidator.equals("expires_at null for permanent")(permBan.expires_at)(null);
  TestValidator.predicate("created_at is ISO 8601")(!!Date.parse(permBan.created_at));

  // 4. (Success) Issue a temporary ban (future expires_at) on new member
  const tempBanTarget = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(tempBanTarget);
  const tempBanReason = "Test temporary ban - will expire soon";
  const futureDate = new Date(Date.now() + 86400 * 1000).toISOString(); // +1 day
  const tempBan = await api.functional.discussionBoard.bans.post(connection, {
    body: {
      member_id: tempBanTarget.id,
      moderator_id: moderatorMember.id,
      ban_reason: tempBanReason,
      permanent: false,
      expires_at: futureDate,
    } satisfies IDiscussionBoardBan.ICreate,
  });
  typia.assert(tempBan);
  TestValidator.equals("ban is temporary")(tempBan.permanent)(false);
  TestValidator.equals("expires_at set")(tempBan.expires_at)(futureDate);
  TestValidator.equals("ban reason")(tempBan.ban_reason)(tempBanReason);

  // 5. (Failure) Try to re-ban with a permanent ban on an already-permanently-banned member
  await TestValidator.error("permanent re-ban should fail")(async () => {
    await api.functional.discussionBoard.bans.post(connection, {
      body: {
        member_id: targetMember.id,
        moderator_id: moderatorMember.id,
        ban_reason: "Second attempt permanent ban - must error",
        permanent: true,
      } satisfies IDiscussionBoardBan.ICreate,
    });
  });

  // 6. (Failure) Try to ban a totally non-existent member
  await TestValidator.error("ban on non-existent member fails")(async () => {
    await api.functional.discussionBoard.bans.post(connection, {
      body: {
        member_id: typia.random<string & tags.Format<"uuid">>(), // random uuid (nonexistent)
        moderator_id: moderatorMember.id,
        ban_reason: "Should fail - fake member",
        permanent: true,
      } satisfies IDiscussionBoardBan.ICreate,
    });
  });

  // 7. (Failure) Try to issue a temporary ban with an expires_at in the past
  const pastDate = new Date(Date.now() - 86400 * 1000).toISOString(); // yesterday
  await TestValidator.error("temp ban with past expires_at fails")(async () => {
    await api.functional.discussionBoard.bans.post(connection, {
      body: {
        member_id: tempBanTarget.id,
        moderator_id: moderatorMember.id,
        ban_reason: "Past expiry - should fail",
        permanent: false,
        expires_at: pastDate,
      } satisfies IDiscussionBoardBan.ICreate,
    });
  });

  // 8. (Failure) Attempt ban by unprivileged user (using new member as moderator_id)
  const ordinaryMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(ordinaryMember);
  await TestValidator.error("ban attempt by basic user should fail")(async () => {
    await api.functional.discussionBoard.bans.post(connection, {
      body: {
        member_id: tempBanTarget.id,
        moderator_id: ordinaryMember.id, // not a moderator/admin
        ban_reason: "Should fail: non-privilege member as moderator_id",
        permanent: true,
      } satisfies IDiscussionBoardBan.ICreate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardBan } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardBan";

/**
 * Validate updating of an existing ban record through the moderator or administrator endpoint.
 *
 * Scenario steps:
 * 1. (Preparation) Create an active temporary ban (valid permanence, future expires_at, valid moderator ID).
 * 2. (a) (Positive) As moderator/admin, update that ban: modify ban_reason, toggle 'permanent', and push expires_at forward.
 *    - Confirm returned record is updated accordingly.
 * 3. (b) (Negative) Try updating a non-existent ban (random UUID), expect not found error.
 * 4. (c) (Negative) Set expires_at to a past value for an active ban, expect validation error.
 * 5. (d) (Negative) Update a soft-deleted ban, expect update is rejected (returns not found or rejected by business rules).
 * 6. (e) (Negative) Attempt update as a non-moderator/non-admin (simulate by using an unprivileged moderator_id – in practice, this test can only be covered if available via dependency injection or token context; in this stub, show structure of the test).
 */
export async function test_api_discussionBoard_bans_test_update_ban_with_valid_and_invalid_data(
  connection: api.IConnection,
) {
  // 1. Preparation: create an active (temporary) ban
  const now = new Date();
  const future = new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000); // +7 days
  const moderator_id = typia.random<string & tags.Format<"uuid">>();
  const member_id = typia.random<string & tags.Format<"uuid">>();

  const ban = await api.functional.discussionBoard.bans.post(connection, {
    body: {
      member_id,
      moderator_id,
      ban_reason: "Temporary harassment ban",
      permanent: false,
      expires_at: future.toISOString(),
    } satisfies IDiscussionBoardBan.ICreate,
  });
  typia.assert(ban);

  // 2. (a) Positive: Update: change reason, make permanent, clear expires_at
  const new_reason = "Escalated to permanent for repeat violation";
  const updated = await api.functional.discussionBoard.bans.putById(connection, {
    id: ban.id,
    body: {
      ban_reason: new_reason,
      permanent: true,
      expires_at: null,
    } satisfies IDiscussionBoardBan.IUpdate,
  });
  typia.assert(updated);
  TestValidator.equals("ban is now permanent")(updated.permanent)(true);
  TestValidator.equals("ban reason updated")(updated.ban_reason)(new_reason);
  TestValidator.equals("expires_at cleared for permanent")(updated.expires_at)(null);

  // 3. (b) Negative: Non-existent ban
  await TestValidator.error("not found for non-existent ban")(
    () =>
      api.functional.discussionBoard.bans.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          ban_reason: "Should not work",
        },
      })
  );

  // 4. (c) Negative: expires_at in the past
