import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * E2E Test: Filter and paginate discussion board tags by keyword
 *
 * This test validates the ability to search and paginate tags in the discussion board system,
 * simulating a user browsing/filtering tags using keyword and paging via PATCH /discussionBoard/tags.
 *
 * Business value: Ensures that filtering and pagination logic for tag browsing works as expected,
 * returning only relevant tags and correct paging information for UI consumers. Covers realistic
 * user workflow for discoverability and content filtering.
 *
 * Step-by-step process:
 * 1. Create a known set of tags ('alpha', 'alphabet', 'beta', 'alphonse', 'gamma', 'delta')
 * 2. Search for tags with name filter 'alph' (should match alpha, alphabet, alphonse)
 * 3. Request page 1 with limit 2 – verify only two results, but total/records are correct
 * 4. All returned tag names must contain the filter text
 * 5. Check pagination.page and total pages match expectation
 * 6. Query with a page beyond total pages – should return no results (edge case)
 */
export async function test_api_discussionBoard_test_search_tags_with_keyword_filtering_and_pagination(
  connection: api.IConnection,
) {
  // 1. Create known tags for the filtering scenario
  const tagsToCreate = [
    { name: "alpha" },
    { name: "alphabet" },
    { name: "beta" },
    { name: "alphonse" },
    { name: "gamma" },
    { name: "delta" },
  ];
  const createdTags: IDiscussionBoardTag[] = [];
  for (const t of tagsToCreate) {
    const tag = await api.functional.discussionBoard.tags.post(connection, {
      body: {
        name: t.name,
        description: `${t.name.charAt(0).toUpperCase()}${t.name.slice(1)} tag`,
      } satisfies IDiscussionBoardTag.ICreate,
    });
    typia.assert(tag);
    createdTags.push(tag);
  }

  // 2. Search for tags by a partial name ('alph'), page 1, limit 2
  const keyword = "alph";
  const limit = 2;
  const page = 1;
  const filterResp = await api.functional.discussionBoard.tags.patch(connection, {
    body: {
      name: keyword,
      limit,
      page,
    } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(filterResp);

  // 3. Calculate reference set for filtered results
  const expected = createdTags.filter((t) => t.name.includes(keyword));
  TestValidator.equals("filtered tag records count")(filterResp.pagination.records)(expected.length);
  filterResp.data.forEach((t) => {
    TestValidator.predicate(`tag name contains '${keyword}'`)(t.name.includes(keyword));
  });

  // 4. Validate number of results on this page, and correct total page calculation
  TestValidator.equals("tags returned in page")(filterResp.data.length)(Math.min(limit, expected.length));
  const totalPages = Math.ceil(expected.length / limit);
  TestValidator.equals("total pagination pages")(filterResp.pagination.pages)(totalPages);

  // 5. Edge case: request a page beyond the last – it should return no results
  const overflowResp = await api.functional.discussionBoard.tags.patch(connection, {
    body: {
      name: keyword,
      limit,
      page: totalPages + 1,
    } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(overflowResp);
  TestValidator.equals("no tags on out-of-bounds page")(overflowResp.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardTag";
import type { IPageIDiscussionBoardTag } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardTag";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate searching for discussion board tags returns correct results when no match is found.
 *
 * This test ensures that when a user attempts to search for tags with a keyword that doesn't exist in any tag's name, the system returns an empty result set with valid pagination metadata (page, limit, records, pages). 
 * Before searching, a baseline set of tags is created that intentionally do not include the negative search keyword. The test then uses PATCH /discussionBoard/tags with the non-existent keyword. The response should have an empty data array, and pagination info should remain consistent and valid (e.g., records=0, pages=0).
 *
 * Steps:
 * 1. Create a baseline set of unique tags using POST /discussionBoard/tags (none of which contain the negative keyword).
 * 2. Search for tags using PATCH /discussionBoard/tags with a unique keyword not present in any tag.
 * 3. Assert that the response data array is empty.
 * 4. Assert that pagination metadata is valid and reflects the absence of records.
 */
export async function test_api_discussionBoard_test_search_tags_with_no_results_returned(
  connection: api.IConnection,
) {
  // 1. Create baseline tags that do NOT contain the negative keyword
  const tagNames = [
    RandomGenerator.alphabets(8),
    RandomGenerator.alphabets(10),
    RandomGenerator.alphabets(7),
  ];
  const tagDescs = [
    RandomGenerator.paragraph()(),
    RandomGenerator.paragraph()(),
    RandomGenerator.paragraph()(),
  ];
  const baselineTags = await Promise.all(
    tagNames.map((name, idx) =>
      api.functional.discussionBoard.tags.post(connection, {
        body: {
          name,
          description: tagDescs[idx],
        } satisfies IDiscussionBoardTag.ICreate,
      })
    )
  );
  baselineTags.forEach(tag => typia.assert(tag));

  // 2. Pick a unique search keyword that is not in baseline tags
  const negativeKeyword = "__no_matching_tag__" + RandomGenerator.alphabets(10);
  if (tagNames.some((n) => n.includes(negativeKeyword)))
    throw new Error("Negative keyword accidentally collides with existing tag!");

  // 3. Search using the negative keyword
  const response = await api.functional.discussionBoard.tags.patch(connection, {
    body: {
      name: negativeKeyword,
      page: 1,
      limit: 10,
    } satisfies IDiscussionBoardTag.IRequest,
  });
  typia.assert(response);

  // 4. Assert data array is empty
  TestValidator.equals("should have no data in search result")(response.data)([]);

  // 5. Assert pagination metadata is correct
  TestValidator.equals("record count is zero")(response.pagination.records)(0);
  TestValidator.equals("page is 1")(response.pagination.current)(1);
  TestValidator.equals("limit is respected")(response.pagination.limit)(10);
  TestValidator.equals("pages is zero")(response.pagination.pages)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
