  const memberOther = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
    },
  });
  typia.assert(memberOther);

  // 2. Create two vote types for different vote actions
  const voteType1 = await api.functional.discussionBoard.voteTypes.post(connection, {
    body: {
      code: `voteA_${RandomGenerator.alphaNumeric(4)}`,
      name: "Vote-A",
      description: "Automated test vote type A",
    },
  });
  typia.assert(voteType1);
  const voteType2 = await api.functional.discussionBoard.voteTypes.post(connection, {
    body: {
      code: `voteB_${RandomGenerator.alphaNumeric(4)}`,
      name: "Vote-B",
      description: "Automated test vote type B",
    },
  });
  typia.assert(voteType2);

  // 3. Create a thread for voting. Owner is memberOwner.
  const thread = await api.functional.discussionBoard.threads.post(connection, {
    body: {
      discussion_board_member_id: memberOwner.id,
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread);

  // 4. Owner creates a vote of type1 on the thread
  const vote = await api.functional.discussionBoard.votes.post(connection, {
    body: {
      vote_type_id: voteType1.id,
      thread_id: thread.id,
    },
  });
  typia.assert(vote);

  // 5. Owner updates their vote to type2 (success)
  const updatedVote = await api.functional.discussionBoard.votes.putById(connection, {
    id: vote.id,
    body: {
      vote_type_id: voteType2.id,
    },
  });
  typia.assert(updatedVote);
  TestValidator.equals("vote type changed")(updatedVote.vote_type_id)(voteType2.id);
  TestValidator.equals("thread id remains")(updatedVote.thread_id)(vote.thread_id);

  // 6. Attempt to update the vote as another member (simulated forbidden)
  TestValidator.error("forbidden: non-owner cannot update vote")(
    async () => {
      await api.functional.discussionBoard.votes.putById(connection, {
        id: vote.id,
        body: {
          vote_type_id: voteType1.id,
        },
      });
    }
  );

  // 7. Owner creates a new thread and a vote of type2. Then attempts to update the first vote to type2 again (should violate uniqueness)
  const thread2 = await api.functional.discussionBoard.threads.post(connection, {
    body: {
      discussion_board_member_id: memberOwner.id,
      discussion_board_category_id: thread.discussion_board_category_id,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    },
  });
  typia.assert(thread2);
  const vote2 = await api.functional.discussionBoard.votes.post(connection, {
    body: {
      vote_type_id: voteType2.id,
      thread_id: thread2.id,
    },
  });
  typia.assert(vote2);
  TestValidator.error("duplicate vote uniqueness constraint")(
    async () => {
      await api.functional.discussionBoard.votes.putById(connection, {
        id: vote.id,
        body: {
          vote_type_id: voteType2.id,
        },
      });
    }
  );

  // 8. Attempt to update a non-existent vote (random uuid, expect not found)
  TestValidator.error("not found for non-existent vote")(
    async () => {
      await api.functional.discussionBoard.votes.putById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
        body: {
          vote_type_id: voteType1.id,
        },
      });
    }
  );
  // Thread deletion scenario skipped: no delete endpoint available in SDK.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardVoteType } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardVoteType";
import type { IDiscussionBoardVote } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardVote";

/**
 * Validate the deletion (soft, with audit trail) of a discussion board vote under different permission scenarios.
 *
 * The business logic under test involves who may delete a vote using DELETE /discussionBoard/votes/{id}. Only the vote owner (voter) and admin roles may delete a vote. Deletion is expected to be a soft deletion (proper audit field update, not hard removal). 
 * The function also validates error handling for attempts to delete wrong/invalid votes, or votes in improper system state.
 *
 * Test workflow:
 * 1. Prepare context by creating: an admin member, a regular vote owner member, and a random other member.
 * 2. Register a new vote type (e.g., "upvote") for use in voting.
 * 3. Register a thread (as discussion context for the vote).
 * 4. Cast a vote of the registered type on the new thread, as the vote owner.
 * 5. Delete the vote by its owner - expect success and soft deletion.
 * 6. Attempt to delete an already deleted vote - expect error.
 * 7. Attempt to delete a non-existent vote ID - expect error.
 * 8. Cast a new vote as the owner again. Attempt to delete as an unrelated (non-owner/non-admin) - expect error.
 * 9. Assign admin privileges to the admin member if possible, then delete the vote as admin - expect success.
 * 10. Cast another vote, delete the target thread, then attempt to delete the vote (on deleted thread) - expect error or defined system handling. (Skipped: No thread deletion API)
 */
export async function test_api_discussionBoard_test_delete_vote_by_owner_and_admin_with_restrictions(
  connection: api.IConnection,
) {
  // 1. Create three members: admin, vote owner, unrelated
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const otherEmail = typia.random<string & tags.Format<"email">>();

  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: "admin!Password#123",
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(adminMember);

  const ownerMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: ownerEmail,
      hashed_password: "owner!Password#456",
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(ownerMember);

  const otherMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: otherEmail,
      hashed_password: "other!Password#789",
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(otherMember);

  // 2. Create a vote type (e.g., upvote)
  const voteType = await api.functional.discussionBoard.voteTypes.post(connection, {
    body: {
      code: "upvote-" + RandomGenerator.alphaNumeric(6),
      name: "Upvote",
      description: "Standard upvote for testing.",
    } satisfies IDiscussionBoardVoteType.ICreate,
  });
  typia.assert(voteType);

  // 3. Create a thread (for voting)
  const thread = await api.functional.discussionBoard.threads.post(connection, {
    body: {
      discussion_board_member_id: ownerMember.id,
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(12),
      body: RandomGenerator.paragraph()(40),
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 4. Owner casts a vote on the thread
  const vote = await api.functional.discussionBoard.votes.post(connection, {
    body: {
      vote_type_id: voteType.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionBoardVote.ICreate,
  });
  typia.assert(vote);

  // 5. Delete the vote as the owner
  const deletedVote = await api.functional.discussionBoard.votes.eraseById(connection, {
    id: vote.id,
  });
  typia.assert(deletedVote);
  TestValidator.equals("deletedVote.id matches")(deletedVote.id)(vote.id);

  // 6. Attempt to delete the vote again - should fail
  await TestValidator.error("Cannot delete already deleted vote")(() =>
    api.functional.discussionBoard.votes.eraseById(connection, { id: vote.id })
  );

  // 7. Attempt to delete a definitely non-existent vote (random UUID)
  await TestValidator.error("Cannot delete non-existent vote")(() =>
    api.functional.discussionBoard.votes.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() })
  );

  // 8. Cast a vote again as owner
  const vote2 = await api.functional.discussionBoard.votes.post(connection, {
    body: {
      vote_type_id: voteType.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionBoardVote.ICreate,
  });
  typia.assert(vote2);

  // Now try to delete as unrelated member (simulate switch to otherMember, which is not the owner)
  // (Assume 'connection' tracks user session; if not, in reality would need login API call here)
  await TestValidator.error("Unrelated user cannot delete vote")(() =>
    api.functional.discussionBoard.votes.eraseById(connection, { id: vote2.id })
  );

  // 9. Try to delete as admin (since real admin login/role switch is not specified, simulate same call)
  // In reality, would require admin session context.
  const deletedByAdmin = await api.functional.discussionBoard.votes.eraseById(connection, {
    id: vote2.id,
  });
  typia.assert(deletedByAdmin);
  TestValidator.equals("deletedByAdmin.id matches")(deletedByAdmin.id)(vote2.id);

  // 10. Vote after deleting thread; create new vote, delete thread, then attempt vote delete
  const thread2 = await api.functional.discussionBoard.threads.post(connection, {
    body: {
      discussion_board_member_id: ownerMember.id,
      discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(),
      title: RandomGenerator.paragraph()(32),
      body: RandomGenerator.paragraph()(50),
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread2);

  const vote3 = await api.functional.discussionBoard.votes.post(connection, {
    body: {
      vote_type_id: voteType.id,
      thread_id: thread2.id,
      post_id: null,
      comment_id: null,
    } satisfies IDiscussionBoardVote.ICreate,
  });
  typia.assert(vote3);

  // (No delete thread API in available functions, so we cannot test case 10 exactly)
  // If we had api.functional.discussionBoard.threads.eraseById we'd use it. Skip this step.
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMention";
import type { IPageIDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Test comprehensive mention list filtering and member RBAC for mentions.
 *
 * Steps:
 * 1. Register two members: actor (who creates a mention) and target (who is mentioned).
 * 2. Actor creates at least one mention targeting the target user (content_type/content_id random).
 * 3. Test mention listing as the target:
 *    a. List mentions received by self:
 *       - Without filters (should see mention(s) received)
 *       - By exact content_type/content_id (should narrow results)
 *       - By date window covering and not covering mention(s)
 *       - By pagination: limit 1, page 1 (should see at least one result), high page (should see empty)
 *       - By sent/actor_member_id=actor: should be empty since target didn't send any
 *    b. List mentions sent by self (should be empty, as target didn't send any)
 * 4. Test mention listing as the actor (who sent mention):
 *    a. List sent mentions (actor_member_id=self) should see what actor sent
 *    b. List received mentions (mentioned_member_id=self) should be empty
 *    c. Test with filters, date windows, pagination as above
 * 5. RBAC test: try to query another member's mentions by filtering for their actor_member_id or mentioned_member_id (while not logged in as them) -- should be 403 forbidden.
 *
 * Each query checks returned IDs, pagination fields, empty results when filters don't match, and error conditions.
 */
export async function test_api_discussionBoard_test_list_mentions_with_various_filters_as_member(connection: api.IConnection) {
  // 1. Register two discussion board members
  const actorEmail = typia.random<string & tags.Format<"email">>();
  const actorUsername = RandomGenerator.alphaNumeric(8);
  const targetEmail = typia.random<string & tags.Format<"email">>();
  const targetUsername = RandomGenerator.alphaNumeric(8);
  const actor = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: actorUsername,
      email: actorEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(actor);
  const target = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: targetUsername,
      email: targetEmail,
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(target);

  // 2. The actor creates a mention targeting the target
  const contentType = RandomGenerator.pick(["post", "comment", "thread"]);
  const contentId = typia.random<string & tags.Format<"uuid">>();
  const mention = await api.functional.discussionBoard.mentions.post(connection, {
    body: {
      mentioned_member_id: target.id,
      content_type: contentType,
      content_id: contentId,
    } satisfies IDiscussionBoardMention.ICreate,
  });
  typia.assert(mention);

  // 3. Test listing as target (received by self)
  // Simulate auth: assume connection is authorized as 'target'

  // a. Received: no filters (should see mention(s))
  let res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
    },
  });
  typia.assert(res);
  TestValidator.predicate("target receives at least 1 mention")(res.data.some(m => m.id === mention.id));

  // b. Filter by content_type/content_id (should see the mention)
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      content_type: contentType,
      content_id: contentId,
    },
  });
  typia.assert(res);
  TestValidator.equals("filter exact mention")(res.data.length)(1);
  TestValidator.equals("correct mention ID")(res.data[0].id)(mention.id);

  // c. Date windows
  const createdDate = mention.created_at;
  const beforeDate = new Date(Date.parse(createdDate) - 1000).toISOString();
  const afterDate = new Date(Date.parse(createdDate) + 1000).toISOString();
  // From after mention: should be empty
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      created_from: afterDate,
    },
  });
  typia.assert(res);
  TestValidator.equals("no mention after mention")(res.data.length)(0);
  // To before mention: should be empty
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      created_to: beforeDate,
    },
  });
  typia.assert(res);
  TestValidator.equals("no mention before mention")(res.data.length)(0);
  // From before, to after: should see the mention
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      created_from: beforeDate,
      created_to: afterDate,
    },
  });
  typia.assert(res);
  TestValidator.predicate("between window includes mention")(res.data.some(m => m.id === mention.id));

  // d. Pagination: limit 1, page 1 (should get 1 but not fail)
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      limit: 1,
      page: 1,
    },
  });
  typia.assert(res);
  TestValidator.equals("pagination limit 1")(res.data.length)(1);

  // e. Pagination: large page for empty
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      limit: 1,
      page: 1000,
    },
  });
  typia.assert(res);
  TestValidator.equals("pagination high page is empty")(res.data.length)(0);

  // f. Actor_member_id=actor (received by target, but sent by actor: should not show, since receiver is not actor)
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: target.id,
      actor_member_id: actor.id,
    },
  });
  typia.assert(res);
  // Should still see the mention, since the actor did send it to target
  TestValidator.equals("mention by both fields")(res.data.length)(1);
  TestValidator.equals("correct mention ID")(res.data[0].id)(mention.id);

  // g. Query as target for sent mentions (actor_member_id: target.id, should be empty)
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      actor_member_id: target.id,
    },
  });
  typia.assert(res);
  TestValidator.equals("target sent no mentions")(res.data.length)(0);

  // 4. Repeat as actor (sent by self, should see sent one; received none)
  // Simulate actor as self
  // Sent by self:
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      actor_member_id: actor.id,
    },
  });
  typia.assert(res);
  TestValidator.equals("actor sent 1 mention")(res.data.length)(1);
  TestValidator.equals("sent mention ID")(res.data[0].id)(mention.id);

  // b. Received as actor (should be empty)
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: actor.id,
    },
  });
  typia.assert(res);
  TestValidator.equals("actor received no mentions")(res.data.length)(0);

  // c. Pagination and content_type/content_id
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      actor_member_id: actor.id,
      limit: 1,
      page: 1,
    },
  });
  typia.assert(res);
  TestValidator.equals("actor pagination one sent")(res.data.length)(1);
  TestValidator.equals("actor sent mention ID paged")(res.data[0].id)(mention.id);

  // d. Pagination large page
  res = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      actor_member_id: actor.id,
      limit: 1,
      page: 1000,
    },
  });
  typia.assert(res);
  TestValidator.equals("actor high page sent empty")(res.data.length)(0);

  // 5. RBAC: Try to see mentions for another user while not logged in as them (forbidden)
  // Simulate NOT logged as target -- try to see target's mentions while logged as actor; should be forbidden.
  // (Assumes backend enforces RBAC based on login)
  await TestValidator.error("actor cannot see target's received mentions")(
    async () => {
      await api.functional.discussionBoard.mentions.patch(connection, {
        body: {
          mentioned_member_id: target.id,
        },
      });
    },
  );

  // Likewise for another actor's sent mentions while logged as target
  await TestValidator.error("target cannot see actor's sent mentions")(
    async () => {
      await api.functional.discussionBoard.mentions.patch(connection, {
        body: {
          actor_member_id: actor.id,
        },
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardAdministrator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardAdministrator";
import type { IDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMention";
import type { IPageIDiscussionBoardMention } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardMention";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing/searching of mentions as a moderator/administrator, covering RBAC audit-compliance.
 *
 * This test ensures that, when logged in as a moderator/administrator, you can:
 * 1. Retrieve all mentions, regardless of sender/recipient (covering all users)
 * 2. Correctly filter by mentioned_member_id and actor_member_id
 * 3. Use pagination options properly
 * 4. See both "sent" and "received" mentions across users (as per RBAC requirements)
 *
 * Steps:
 * 1. Create three members: two regular, one to be escalated as admin
 * 2. Assign administrator privileges to one member
 * 3. Create mention records across combinations (member1 → member2, member2 → member1, admin → member1)
 * 4. As admin, list ALL mentions; verify all created mentions are present
 * 5. Filter by mentioned_member_id ("mentions received"), check filtering correctness
 * 6. Filter by actor_member_id ("mentions sent"), check filtering correctness
 * 7. Use pagination, and verify returned count/limit
 */
export async function test_api_discussionBoard_test_list_mentions_as_moderator_includes_all_mentions(
  connection: api.IConnection,
) {
  // 1. Register three members: two normal + one for admin assignment
  const password1 = RandomGenerator.alphaNumeric(12);
  const member1 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: password1,
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    },
  });
  typia.assert(member1);
  const password2 = RandomGenerator.alphaNumeric(12);
  const member2 = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: password2,
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    },
  });
  typia.assert(member2);
  const adminPassword = RandomGenerator.alphaNumeric(12);
  const adminMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: adminPassword,
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    },
  });
  typia.assert(adminMember);

  // 2. Escalate admin privileges
  const admin = await api.functional.discussionBoard.administrators.post(connection, {
    body: {
      member_id: adminMember.id,
    },
  });
  typia.assert(admin);

  // 3. Create cross-mention events:
  // member1 → member2 (post), member2 → member1 (comment), admin → member1 (post)
  const content_type_a = "post";
  const content_type_b = "comment";
  const content_id_a = typia.random<string & tags.Format<"uuid">>();
  const content_id_b = typia.random<string & tags.Format<"uuid">>();

  // member1 mentions member2
  const mention1 = await api.functional.discussionBoard.mentions.post(connection, {
    body: {
      mentioned_member_id: member2.id,
      content_type: content_type_a,
      content_id: content_id_a,
    },
  });
  typia.assert(mention1);
  // member2 mentions member1
  const mention2 = await api.functional.discussionBoard.mentions.post(connection, {
    body: {
      mentioned_member_id: member1.id,
      content_type: content_type_b,
      content_id: content_id_b,
    },
  });
  typia.assert(mention2);
  // admin mentions member1
  const mention3 = await api.functional.discussionBoard.mentions.post(connection, {
    body: {
      mentioned_member_id: member1.id,
      content_type: content_type_a,
      content_id: content_id_b,
    },
  });
  typia.assert(mention3);

  // 4. As admin: list all mentions, ensure all test mentions are found
  const allMentions = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {},
  });
  typia.assert(allMentions);
  const allMentionIds = allMentions.data.map((m) => m.id);
  TestValidator.predicate("all created mentions are found in admin view")(
    allMentionIds.includes(mention1.id) &&
    allMentionIds.includes(mention2.id) &&
    allMentionIds.includes(mention3.id)
  );

  // 5. Filter: mentions where mentioned_member_id==member1.id (mentions 'received' by member1)
  const mentionsOfMember1 = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      mentioned_member_id: member1.id,
    },
  });
  typia.assert(mentionsOfMember1);
  TestValidator.predicate("filter: all mentions where member1 is mentioned")(
    mentionsOfMember1.data.every((m) => m.mentioned_member_id === member1.id)
  );
  TestValidator.predicate("filter: known mentions to member1 exist")(
    mentionsOfMember1.data.some((m) => m.id === mention2.id || m.id === mention3.id)
  );

  // 6. Filter: mentions sent by member1 (actor_member_id == member1.id)
  const mentionsFromMember1 = await api.functional.discussionBoard.mentions.patch(connection, {
    body: {
      actor_member_id: member1.id,
    },
  });
  typia.assert(mentionsFromMember1);
  TestValidator.predicate("filter: all mentions sent by member1")(
