 * 4. 밴 상태의 회원으로 멘션을 시도 시, 반드시 에러(Forbidden)가 발생해야 한다.
 * 5. 같은 금지된 회원의 멘션 반복 시도 역시 일관되게 차단됨을 검증한다.
 */
export async function test_api_discussionBoard_test_create_mention_forbidden_by_ban_or_permission(
