      } satisfies IDiscussionBoardMember.ICreate,
    });
  typia.assert(member1);

  // 2. 제재(밴) 등록: 별도 moderator 생성 및 밴 적용
  const moderator: IDiscussionBoardMember =
    await api.functional.discussionBoard.members.post(connection, {
