 * Edge case: deleting already soft-deleted attachment (should yield conflict or not-modified error);
 * deleting non-existent attachment (should return not found).
 * On successful deletion, validate that deleted_at is set and attachment is not returned in future list queries unless including deleted records explicitly.
 * Test restoration logic if such feature is supported (for audit purposes).
 *
 * 1. Register three users: owner, another member, and admin (simulate via naming convention).
 * 2. Owner creates a post (thread id is random — simulated, as thread creation API is not available, so use random UUID).
 * 3. Owner uploads an attachment for the post.
 * 4. Owner deletes the attachment (should succeed, expect soft-deletion — validate deleted_at).
 * 5. Attempt to delete again as owner (should fail: already deleted, expect error).
 * 6. Attempt to delete same attachment as another member (should fail: forbidden).
 * 7. Attempt to delete same attachment as admin (should succeed or forbidden, depending on business logic).
 * 8. Attempt to delete a non-existent attachment (expect not found error).
 * Note: Restoration and filtering for deleted not implemented — attachment listing/list-by-id is not in API set.
 */
export async function test_api_discussionBoard_test_delete_attachment_as_owner_and_admin_vs_forbidden(connection: api.IConnection) {
  // Register OWNER
  const ownerEmail = typia.random<string & tags.Format<"email">>();
  const owner = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: ownerEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: "OwnerUser",
      profile_image_url: null,
    }
  });
  typia.assert(owner);

  // Register ANOTHER MEMBER
  const memberEmail = typia.random<string & tags.Format<"email">>();
  const member = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: memberEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: "OtherUser",
      profile_image_url: null,
    }
  });
  typia.assert(member);

  // Register ADMIN (simulated by display_name containing 'admin')
  const adminEmail = typia.random<string & tags.Format<"email">>();
  const admin = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphaNumeric(8),
      email: adminEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: "AdminUser",
      profile_image_url: null,
    }
  });
  typia.assert(admin);

  // Owner creates post (thread id simulated)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      discussion_board_thread_id: threadId,
      discussion_board_member_id: owner.id,
      body: RandomGenerator.paragraph()(),
    }
  });
  typia.assert(post);

  // Owner uploads attachment to the post
  const attachment = await api.functional.discussionBoard.attachments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      file_name: "testfile.txt",
      file_uri: `https://files.example.com/${RandomGenerator.alphaNumeric(12)}`,
      content_type: "text/plain",
      content_hash: RandomGenerator.alphaNumeric(32)
    }
  });
  typia.assert(attachment);
  TestValidator.equals("owner on attachment")(attachment.discussion_board_member_id)(owner.id);

  // OWNER deletes own attachment: should succeed
  await api.functional.discussionBoard.attachments.eraseById(connection, { id: attachment.id });

  // Try to delete again as owner: should fail (already deleted)
  await TestValidator.error("deleting already deleted attachment fails")(
    async () => {
      await api.functional.discussionBoard.attachments.eraseById(connection, { id: attachment.id });
    }
  );

  // Create another attachment for non-owner/admin tests
  const attachment2 = await api.functional.discussionBoard.attachments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      file_name: "testfile2.txt",
      file_uri: `https://files.example.com/${RandomGenerator.alphaNumeric(12)}`,
      content_type: "text/plain",
      content_hash: RandomGenerator.alphaNumeric(32)
    }
  });
  typia.assert(attachment2);
  TestValidator.equals("owner on attachment2")(attachment2.discussion_board_member_id)(owner.id);

  // Try to delete as ANOTHER MEMBER: should fail (no permission)
  await TestValidator.error("another member cannot delete not-owned attachment")(
    async () => {
      await api.functional.discussionBoard.attachments.eraseById(connection, { id: attachment2.id });
    }
  );

  // Try to delete as ADMIN (simulate by display_name "AdminUser"): test effect (per business logic, pass on error or success)
  try {
    await api.functional.discussionBoard.attachments.eraseById(connection, { id: attachment2.id });
  } catch (_) {}

  // Try to delete non-existent attachment (random UUID)
  await TestValidator.error("deleting non-existent attachment yields not found")(
    async () => {
      await api.functional.discussionBoard.attachments.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() });
    }
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";
import type { IPageIDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIDiscussionBoardReport";
import type { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";

/**
 * Validate listing and filtering of moderation reports as a moderator.
 *
 * This test simulates a real-world moderation workflow on a discussion board:
 * 1. Register a general member who will create content and submit reports
 * 2. Member creates a thread, a post, and a comment so each can be reported
 * 3. Member submits three separate reports (thread, post, comment)
 * 4. Register a second member to become the moderator
 * 5. Grant moderator rights by role assignment
 * 6. As moderator, list reports in multiple ways:
 *    - All reports (unfiltered)
 *    - Filter by reporter
 *    - Filter by content type (thread, post, comment)
 *    - Filter by status (pending, resolved)
 *    - Filter by date ranges
 *    - Paginate results (limit/page)
 *    - Use filters that match no results
 * 7. Verify:
 *    - Report data matches filters
 *    - Pagination is correct (count, page, etc.)
 *    - Permissions: Only the moderator sees *all* reports
 *    - Edge: Zero-result queries handled cleanly
 */
export async function test_api_discussionBoard_test_list_reports_with_various_filters_and_pagination_as_moderator(
  connection: api.IConnection,
) {
  // 1. Register a member (the reporter/content creator)
  const member: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(member);

  // 2. Register a thread (with random category ID)
  const categoryId = typia.random<string & tags.Format<"uuid">>();
  const thread: IDiscussionBoardThread = await api.functional.discussionBoard.threads.post(connection, {
    body: {
      discussion_board_member_id: member.id,
      discussion_board_category_id: categoryId,
      title: RandomGenerator.paragraph()(1),
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardThread.ICreate,
  });
  typia.assert(thread);

  // 3. Register a post (as reply to the thread)
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      discussion_board_thread_id: thread.id,
      discussion_board_member_id: member.id,
      body: RandomGenerator.content()()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 4. Register a comment (on the post)
  const comment: IDiscussionBoardComment = await api.functional.discussionBoard.comments.post(connection, {
    body: {
      discussion_board_post_id: post.id,
      parent_id: null,
      body: RandomGenerator.paragraph()(1),
    } satisfies IDiscussionBoardComment.ICreate,
  });
  typia.assert(comment);

  // 5. Submit reports on thread, post, and comment, with different reasons
  const reportThread: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: member.id,
      thread_id: thread.id,
      post_id: null,
      comment_id: null,
      reason: "thread rule violation",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(reportThread);

  const reportPost: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: member.id,
      thread_id: null,
      post_id: post.id,
      comment_id: null,
      reason: "post inappropriate",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(reportPost);

  const reportComment: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: member.id,
      thread_id: null,
      post_id: null,
      comment_id: comment.id,
      reason: "comment spam",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(reportComment);

  // 6. Register a moderator member
  const moderatorMember: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(16),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(moderatorMember);

  // 7. Assign moderator role
  const moderatorRole: IDiscussionBoardModerator = await api.functional.discussionBoard.moderators.post(connection, {
    body: {
      member_id: moderatorMember.id,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(moderatorRole);

  // 8. As moderator, search/list all reports (no filter)
  const allReports = await api.functional.discussionBoard.reports.patch(connection, {
    body: {} satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(allReports);
  TestValidator.predicate("all 3 test reports present")(allReports.data.length >= 3);

  // 9. Filter by reporter
  const byReporter = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      reporter_member_id: member.id,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byReporter);
  TestValidator.equals("reporter filtered")(byReporter.data.every(rep => rep.reporter_member_id === member.id))(true);

  // 10. Filter by thread_id, post_id, comment_id respectively
  const byThread = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      thread_id: thread.id,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byThread);
  TestValidator.equals("thread report only")(byThread.data.length)(1);
  TestValidator.equals("thread id match")(byThread.data[0]?.thread_id)(thread.id);

  const byPost = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      post_id: post.id,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byPost);
  TestValidator.equals("post report only")(byPost.data.length)(1);
  TestValidator.equals("post id match")(byPost.data[0]?.post_id)(post.id);

  const byComment = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      comment_id: comment.id,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byComment);
  TestValidator.equals("comment report only")(byComment.data.length)(1);
  TestValidator.equals("comment id match")(byComment.data[0]?.comment_id)(comment.id);

  // 11. Filter by reason (should return only matching report)
  const byReason = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      reason: "post inappropriate",
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byReason);
  TestValidator.equals("reason filtered")(byReason.data.every(rep => rep.reason === "post inappropriate"))(true);

  // 12. By status (assume all are still 'pending')
  const byStatus = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      status: "pending",
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byStatus);
  TestValidator.predicate("all status pending")(byStatus.data.every(rep => rep.status === "pending"));

  // 13. By date ranges
  const since = new Date(Date.now() - 1000 * 60 * 10).toISOString();
  const until = new Date(Date.now() + 1000 * 60 * 10).toISOString();
  const byDate = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      created_at_from: since,
      created_at_to: until,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(byDate);
  TestValidator.equals("date range query")(byDate.data.length >= 3)(true);

  // 14. Pagination: limit/page
  const paged = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      limit: 2,
      page: 1,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(paged);
  TestValidator.equals("pagination: page 1, limit 2")(paged.data.length)(2);
  TestValidator.equals("pagination: total count")(paged.pagination.records)(allReports.pagination.records);

  // 15. Pagination: empty page (page that can't have data)
  const emptyPage = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      limit: 3,
      page: 100,
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(emptyPage);
  TestValidator.equals("empty pagination")(emptyPage.data.length)(0);

  // 16. Filters that match no reports
  const noMatch = await api.functional.discussionBoard.reports.patch(connection, {
    body: {
      reporter_member_id: typia.random<string & tags.Format<"uuid">>(),
      reason: "nonsense reasoning",
    } satisfies IDiscussionBoardReport.IRequest,
  });
  typia.assert(noMatch);
  TestValidator.equals("zero result filter")(noMatch.data.length)(0);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate viewing of a moderation report's details by both the reporting member and a moderator, and enforce proper permissions/response shapes.
 *
 * This test ensures only authorized members (reporter, moderators) can retrieve the detail of a given report by its ID and that all visible information is correct, while access is forbidden for unrelated members and an error is thrown for non-existent IDs.
 *
 * Step-by-step process:
 * 1. Register a regular member (the 'reporter')
 * 2. Register another member (as an unrelated user)
 * 3. Register a third member (future moderator)
 * 4. Create a post as the reporter (use random valid thread UUID as placeholder, since thread management is out of scope)
 * 5. File a report referencing the post as the reporter
 * 6. Retrieve the report by ID as the reporter (should succeed and match submission + created object)
 * 7. Assign moderator rights
 * 8. Retrieve by ID as moderator & validate
 * 9. Attempt to retrieve a non-existent report
 *
 * NOTE: This test omits permission boundary checks (e.g., attempts to forcibly switch Authorization in the same connection) as connection-based session tokens/user switching is not supported by the provided APIs. Only actual business operations are tested.
 */
export async function test_api_discussionBoard_test_get_report_detail_by_id_as_reporter_and_moderator(
  connection: api.IConnection,
) {
  // 1. Register reporter (member)
  const reporterEmail = typia.random<string & tags.Format<"email">>();
  const reporterUsername = RandomGenerator.alphaNumeric(9);
  const reporterPassword = RandomGenerator.alphaNumeric(12);

  const reporter = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: reporterUsername,
        email: reporterEmail,
        hashed_password: reporterPassword,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(reporter);

  // 2. Register unrelated member
  const unrelatedEmail = typia.random<string & tags.Format<"email">>();
  const unrelatedUsername = RandomGenerator.alphaNumeric(9);
  const unrelatedPassword = RandomGenerator.alphaNumeric(12);

  const unrelated = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: unrelatedUsername,
        email: unrelatedEmail,
        hashed_password: unrelatedPassword,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(unrelated);

  // 3. Register moderator candidate
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderatorUsername = RandomGenerator.alphaNumeric(9);
  const moderatorPassword = RandomGenerator.alphaNumeric(12);

  const moderator = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: moderatorUsername,
        email: moderatorEmail,
        hashed_password: moderatorPassword,
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(moderator);

  // 4. Create a post as the reporter (simulate valid thread id)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(
    connection,
    {
      body: {
        discussion_board_thread_id: threadId,
        discussion_board_member_id: reporter.id,
        body: RandomGenerator.paragraph()(),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // 5. File a report referencing the post as the reporter
  const reportReason = "Prohibited content";
  const report = await api.functional.discussionBoard.reports.post(
    connection,
    {
      body: {
        reporter_member_id: reporter.id,
        thread_id: null, // Not reporting a thread
        post_id: post.id,
        comment_id: null, // Not reporting a comment
        reason: reportReason,
      } satisfies IDiscussionBoardReport.ICreate,
    },
  );
  typia.assert(report);

  // 6. Retrieve the report as the reporter & validate output
  const readAsReporter = await api.functional.discussionBoard.reports.getById(
    connection,
    { id: report.id },
  );
  typia.assert(readAsReporter);
  TestValidator.equals("report matches ID")(readAsReporter.id)(report.id);
  TestValidator.equals("reporter matches")(readAsReporter.reporter_member_id)(reporter.id);
  TestValidator.equals("post matches")(readAsReporter.post_id)(post.id);
  TestValidator.equals("reason matches")(readAsReporter.reason)(reportReason);

  // 7. Assign moderator rights
  const moderatorAssignment = await api.functional.discussionBoard.moderators.post(
    connection,
    {
      body: {
        member_id: moderator.id,
      } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(moderatorAssignment);

  // 8. Retrieve by ID as moderator & validate
  // (Since session switching is not natively supported, this is a logical/sequence demonstration)
  // In a real system, you would use a new authenticated connection for moderator.
  const readAsModerator = await api.functional.discussionBoard.reports.getById(
    connection,
    { id: report.id },
  );
  typia.assert(readAsModerator);
  TestValidator.equals("report ID for moderator")(readAsModerator.id)(report.id);
  TestValidator.equals("moderator assignment permitted")(typeof readAsModerator.status === "string")(true);

  // 9. Attempt to retrieve a non-existent report
  await TestValidator.error("not found for invalid ID")(
    async () => {
      await api.functional.discussionBoard.reports.getById(connection, {
        id: typia.random<string & tags.Format<"uuid">>(),
      });
    },
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardThread } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardThread";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardComment } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardComment";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Test creating moderation reports on threads, posts, and comments, including failure cases for non-existent targets, duplicates,
 * and unprivileged members, as well as guest/unauthenticated access.
 *
 * This function verifies:
 *   1. A valid member can submit reports on threads, posts, and comments they do not own.
 *   2. Reporting fails for invalid (non-existent) thread, post, or comment ids.
 *   3. Duplicate report (same member, same target) is prevented.
 *   4. After banning/soft-deleting a member account, reporting is forbidden for that member.
 *   5. Guests/unauthenticated users cannot create reports.
 *
 * Steps:
 *   1. Register a member (Member1)
 *   2. Register a second member (Member2) to be the owner of target content
 *   3. Member2 creates a thread
 *   4. Member2 creates a post in the thread
 *   5. Member2 adds a comment to the post
 *   6. Member1 files a report on the thread (success)
 *   7. Member1 files a report on the post (success)
 *   8. Member1 files a report on the comment (success)
 *   9. Member1 attempts to re-report the same thread (should fail as duplicate)
 *   10. Member1 attempts to report non-existent thread/post/comment (should fail)
 *   11. Ban/soft-delete Member1, and ensure they can no longer report (should fail)
 *   12. Attempt to report as guest/no authentication (should fail)
 */
export async function test_api_discussionBoard_test_create_report_with_valid_and_invalid_targets(
  connection: api.IConnection,
) {
  // 1. Register Member1
  const member1Create = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
  } satisfies IDiscussionBoardMember.ICreate;
  const member1 = await api.functional.discussionBoard.members.post(connection, { body: member1Create });
  typia.assert(member1);

  // 2. Register Member2 (content owner)
  const member2Create = {
    username: RandomGenerator.alphaNumeric(12),
    email: typia.random<string & tags.Format<"email">>(),
    hashed_password: RandomGenerator.alphaNumeric(16),
    display_name: RandomGenerator.name(),
    profile_image_url: null,
  } satisfies IDiscussionBoardMember.ICreate;
  const member2 = await api.functional.discussionBoard.members.post(connection, { body: member2Create });
  typia.assert(member2);

  // 3. Member2 creates a thread
  const threadCreate = {
    discussion_board_member_id: member2.id,
    discussion_board_category_id: typia.random<string & tags.Format<"uuid">>(), // As category is not handled in scenario, mock a UUID
    title: RandomGenerator.paragraph()(1),
    body: RandomGenerator.paragraph()(2),
  } satisfies IDiscussionBoardThread.ICreate;
  const thread = await api.functional.discussionBoard.threads.post(connection, { body: threadCreate });
  typia.assert(thread);

  // 4. Member2 creates a post in the thread
  const postCreate = {
    discussion_board_thread_id: thread.id,
    discussion_board_member_id: member2.id,
    body: RandomGenerator.paragraph()(2),
  } satisfies IDiscussionBoardPost.ICreate;
  const post = await api.functional.discussionBoard.posts.post(connection, { body: postCreate });
  typia.assert(post);

  // 5. Member2 adds a comment to the post
  const commentCreate = {
    discussion_board_post_id: post.id,
    parent_id: null,
    body: RandomGenerator.paragraph()(1),
  } satisfies IDiscussionBoardComment.ICreate;
  const comment = await api.functional.discussionBoard.comments.post(connection, { body: commentCreate });
  typia.assert(comment);

  // 6. Member1 reports the thread
  const reportOnThreadInput = {
    reporter_member_id: member1.id,
    thread_id: thread.id,
    post_id: null,
    comment_id: null,
    reason: "Spam or irrelevant content",
  } satisfies IDiscussionBoardReport.ICreate;
  const threadReport = await api.functional.discussionBoard.reports.post(connection, { body: reportOnThreadInput });
  typia.assert(threadReport);
  TestValidator.equals("report on thread target")(threadReport.thread_id)(thread.id);
  TestValidator.equals("reporter matches")(threadReport.reporter_member_id)(member1.id);

  // 7. Member1 reports the post
  const reportOnPostInput = {
    reporter_member_id: member1.id,
    thread_id: null,
    post_id: post.id,
    comment_id: null,
    reason: "Offensive language",
  } satisfies IDiscussionBoardReport.ICreate;
  const postReport = await api.functional.discussionBoard.reports.post(connection, { body: reportOnPostInput });
  typia.assert(postReport);
  TestValidator.equals("report on post target")(postReport.post_id)(post.id);
  TestValidator.equals("reporter matches")(postReport.reporter_member_id)(member1.id);

  // 8. Member1 reports the comment
  const reportOnCommentInput = {
    reporter_member_id: member1.id,
    thread_id: null,
    post_id: null,
    comment_id: comment.id,
    reason: "Personal attack",
  } satisfies IDiscussionBoardReport.ICreate;
  const commentReport = await api.functional.discussionBoard.reports.post(connection, { body: reportOnCommentInput });
  typia.assert(commentReport);
  TestValidator.equals("report on comment target")(commentReport.comment_id)(comment.id);
  TestValidator.equals("reporter matches")(commentReport.reporter_member_id)(member1.id);

  // 9. Duplicate report on thread (should fail)
  await TestValidator.error("duplicate thread report fails")(() =>
    api.functional.discussionBoard.reports.post(connection, { body: reportOnThreadInput })
  );

  // 10. Reporting with non-existent IDs (should fail for each type)
  const nonExistentUUID = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error("report non-existent thread")(() =>
    api.functional.discussionBoard.reports.post(connection, {
      body: {
        reporter_member_id: member1.id,
        thread_id: nonExistentUUID,
        post_id: null,
        comment_id: null,
        reason: "Attempt on non-existent thread",
      } satisfies IDiscussionBoardReport.ICreate
    })
  );
  await TestValidator.error("report non-existent post")(() =>
    api.functional.discussionBoard.reports.post(connection, {
      body: {
        reporter_member_id: member1.id,
        thread_id: null,
        post_id: nonExistentUUID,
        comment_id: null,
        reason: "Attempt on non-existent post",
      } satisfies IDiscussionBoardReport.ICreate
    })
  );
  await TestValidator.error("report non-existent comment")(() =>
    api.functional.discussionBoard.reports.post(connection, {
      body: {
        reporter_member_id: member1.id,
        thread_id: null,
        post_id: null,
        comment_id: nonExistentUUID,
        reason: "Attempt on non-existent comment",
      } satisfies IDiscussionBoardReport.ICreate
    })
  );

  // 11. Soft-delete/ban Member1 and check reporting is forbidden
  await api.functional.discussionBoard.members.eraseById(connection, { id: member1.id });
  await TestValidator.error("banned/deleted member cannot report")(() =>
    api.functional.discussionBoard.reports.post(connection, { body: reportOnThreadInput })
  );

  // 12. Reporting as guest/unauthenticated user (simulate with new connection object, no member context)
  const guestConnection = { ...connection, headers: {} };
  await TestValidator.error("guest cannot report")(() =>
    api.functional.discussionBoard.reports.post(guestConnection, { body: reportOnThreadInput })
  );
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * 테스트: 동일한 회원이 동일한 컨텐츠(포스트)에 대해 중복 신고를 제출하면 차단되어야 함을 검증한다.
 *
 * 1. 신규 회원을 등록한다 (신고자A)
 * 2. 신고 대상이 될 포스트를 생성한다 (A가 작성자, 또는 랜덤 작성자)
 * 3. 신고자A가 해당 포스트에 대해 reason="Spam" 으로 신고를 최초 1회 제출한다
 * 4. 즉시 동일 회원 A가 동일 포스트+동일 reason 으로 신고를 다시 시도한다
 *    - 시스템이 중복/스팸 방지 로직으로 차단하여, 에러가 발생해야 한다
 * 5. reason 만 다르게(예: reason="Abuse") 두고 신고하면 접수되어야 한다 (성공)
 * 6. 다른 신규 회원(신고자B)이 동일 포스트에 동일 reason 으로 신고하면 접수되어야 한다 (성공)
 */
export async function test_api_discussionBoard_test_create_report_duplicate_prevention_and_spam_guardrails(
  connection: api.IConnection,
) {
  // 1. 신고자A 회원 생성
  const memberA = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberA);

  // 2. 타겟 포스트 생성 (A 본인이 작성자로 지정)
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      discussion_board_thread_id: threadId,
      discussion_board_member_id: memberA.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. 신고자A, 포스트에 reason="Spam"으로 신고 (최초)
  const initialReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: memberA.id,
      post_id: post.id,
      reason: "Spam",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(initialReport);

  // 4. 동일 회원A, 동일 포스트+동일 reason으로 신고(중복시도) - 실패 예상
  await TestValidator.error("duplicate report prevention")(async () => {
    await api.functional.discussionBoard.reports.post(connection, {
      body: {
        reporter_member_id: memberA.id,
        post_id: post.id,
        reason: "Spam",
      } satisfies IDiscussionBoardReport.ICreate,
    });
  });

  // 5. reason만 다르게(예: Abuse) 신고 (성공)
  const diffReasonReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: memberA.id,
      post_id: post.id,
      reason: "Abuse",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(diffReasonReport);

  // 6. 신고자B 신규 회원 등록 및 동일 포스트, 동일 reason("Spam") 신고 (성공)
  const memberB = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: typia.random<string & tags.Format<"email">>(),
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(memberB);

  const diffMemberReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: memberB.id,
      post_id: post.id,
      reason: "Spam",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(diffMemberReport);
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Validate moderator update of an existing content moderation report.
 *
 * This test covers a workflow where a typical user reports a post, a moderator account reviews and updates the status of the report (e.g., resolving it with notes), and verifies correct state transitions. It also checks unauthorized update attempts by a non-moderator and tests business rule enforcement for status fields.
 *
 * Steps:
 * 1. Register a normal member to act as a content reporter.
 * 2. Create a new post as the reporter to generate content eligible for reporting.
 * 3. Reporter files a moderation report referencing the post (reason: 'offensive').
 * 4. Register a second member account to be the moderator; escalate this account via moderator assignment API.
 * 5. As the moderator, perform a report update: set status to 'resolved' with moderation notes. Validate response fields: status, resolution_notes, resolved_at, moderator_id.
 * 6. Confirm status/notes are reflected in the report entity.
 * 7. Edge: As a random unrelated member, attempt to perform a report update—should fail with a permission error.
 * 8. Edge: Send an update with an invalid status value (e.g., random nonsense)—should return a validation or workflow error.
 * 9. (Omit if not supported by API) Check that audit metadata (updated_at, resolved_at, moderator_id) matches update.
 */
export async function test_api_discussionBoard_test_update_report_status_and_resolution_as_moderator(
  connection: api.IConnection,
) {
  // 1. Register a normal content-reporting member
  const reporterEmail = typia.random<string & tags.Format<"email">>();
  const reporter: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: reporterEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(reporter);

  // 2. Create a post as this reporter, mock a thread id
  const threadId = typia.random<string & tags.Format<"uuid">>();
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.posts.post(connection, {
    body: {
      discussion_board_thread_id: threadId,
      discussion_board_member_id: reporter.id,
      body: RandomGenerator.paragraph()(),
    } satisfies IDiscussionBoardPost.ICreate,
  });
  typia.assert(post);

  // 3. Reporter files a moderation report referencing the post
  const report: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(connection, {
    body: {
      reporter_member_id: reporter.id,
      post_id: post.id,
      reason: "offensive",
    } satisfies IDiscussionBoardReport.ICreate,
  });
  typia.assert(report);

  // 4. Register moderator account and escalate privilege
  const moderatorEmail = typia.random<string & tags.Format<"email">>();
  const moderator: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: moderatorEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(moderator);

  const modAssignment = await api.functional.discussionBoard.moderators.post(connection, {
    body: {
      member_id: moderator.id,
    } satisfies IDiscussionBoardModerator.ICreate,
  });
  typia.assert(modAssignment);

  // 5. Moderator performs update on the report
  const updateResult: IDiscussionBoardReport = await api.functional.discussionBoard.reports.putById(connection, {
    id: report.id,
    body: {
      moderator_id: moderator.id,
      status: "resolved",
      resolution_notes: "Resolved with review.",
    } satisfies IDiscussionBoardReport.IUpdate,
  });
  typia.assert(updateResult);
  TestValidator.equals("report updated to resolved")(updateResult.status)("resolved");
  TestValidator.equals("resolution notes reflected")(updateResult.resolution_notes)("Resolved with review.");
  TestValidator.equals("moderator assigned")(updateResult.moderator_id)(moderator.id);
  TestValidator.predicate("resolved_at set")(!!updateResult.resolved_at);

  // 6. Confirm in report entity fields
  TestValidator.equals("status reflected")(updateResult.status)("resolved");
  TestValidator.equals("resolution notes reflected")(updateResult.resolution_notes)("Resolved with review.");

  // 7. Edge: unrelated member tries to update—should fail
  const unrelatedEmail = typia.random<string & tags.Format<"email">>();
  const unrelated: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(connection, {
    body: {
      username: RandomGenerator.alphabets(8),
      email: unrelatedEmail,
      hashed_password: RandomGenerator.alphaNumeric(12),
      display_name: RandomGenerator.name(),
      profile_image_url: null,
    } satisfies IDiscussionBoardMember.ICreate,
  });
  typia.assert(unrelated);
  TestValidator.error("non-moderator update should fail")(async () => {
    await api.functional.discussionBoard.reports.putById(connection, {
      id: report.id,
      body: {
        moderator_id: unrelated.id,
        status: "resolved",
        resolution_notes: "Should not succeed.",
      } satisfies IDiscussionBoardReport.IUpdate,
    });
  });

  // 8. Edge: invalid status value should fail
  TestValidator.error("invalid status value fails")(async () => {
    await api.functional.discussionBoard.reports.putById(connection, {
      id: report.id,
      body: {
        moderator_id: moderator.id,
        status: "not_real_status",
        resolution_notes: "Invalid status test.",
      } satisfies IDiscussionBoardReport.IUpdate,
    });
  });
}

import { ArrayUtil, RandomGenerator, TestValidator } from "@nestia/e2e";
import { IConnection } from "@nestia/fetcher";
import typia, { tags } from "typia";

import api from "@ORGANIZATION/PROJECT-api";
import type { IDiscussionBoardMember } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardMember";
import type { IDiscussionBoardModerator } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardModerator";
import type { IDiscussionBoardPost } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardPost";
import type { IDiscussionBoardReport } from "@ORGANIZATION/PROJECT-api/lib/structures/IDiscussionBoardReport";

/**
 * Test soft-deleting a moderation report both as report owner and as moderator.
 *
 * This test validates the following flows:
 *  - A regular member (Member A) can soft-delete (erase) their own report; deletion is confirmed by absence of errors.
 *  - Double-deleting the same report is rejected (conflict or error expected).
 *  - Deleting a non-existent report ID yields a not-found error.
 *  - A moderator (Member B) can file and delete a report; elevated permissions allow for deletion regardless of ownership.
 *  - A non-owner/non-moderator (Member A) cannot delete another's report (forbidden/unauthorized error).
 *
 * Steps:
 * 1. Register Member A (regular member).
 * 2. Register Member B (to become moderator) and grant moderator role.
 * 3. Member A creates a post (in a random thread).
 * 4. Member A files a report on the post.
 * 5. Member A deletes (soft-deletes) their own report — expect success.
 * 6. Attempt double-deletion of A's report — expect error.
 * 7. Attempt to delete a non-existent report ID — expect error.
 * 8. Member B (now moderator) files a report, deletes it as moderator — expect success.
 * 9. Attempt to delete B's report as Member A (unauthorized) — expect error.
 *
 * Note: The API does not expose report listing or direct audit/retrieval endpoints,
 * so no programmatic assertion is made about data retention/audit trail; soft-deletion
 * is validated via lack of errors on erase and correct error thrown in edge cases.
 */
export async function test_api_discussionBoard_test_soft_delete_report_as_report_owner_and_moderator(
  connection: api.IConnection,
) {
  // Step 1: Register Member A
  const memberA_email = typia.random<string & tags.Format<"email">>();
  const memberA_username = RandomGenerator.alphaNumeric(10);
  const memberA: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: memberA_username,
        email: memberA_email,
        hashed_password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberA);

  // Step 2: Register Member B and grant moderator
  const memberB_email = typia.random<string & tags.Format<"email">>();
  const memberB_username = RandomGenerator.alphaNumeric(10);
  const memberB: IDiscussionBoardMember = await api.functional.discussionBoard.members.post(
    connection,
    {
      body: {
        username: memberB_username,
        email: memberB_email,
        hashed_password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        profile_image_url: null,
      } satisfies IDiscussionBoardMember.ICreate,
    },
  );
  typia.assert(memberB);

  const moderator: IDiscussionBoardModerator = await api.functional.discussionBoard.moderators.post(
    connection,
    {
      body: { member_id: memberB.id } satisfies IDiscussionBoardModerator.ICreate,
    },
  );
  typia.assert(moderator);

  // Step 3: Member A creates a post using a new thread
  const thread_id = typia.random<string & tags.Format<"uuid">>();
  const post: IDiscussionBoardPost = await api.functional.discussionBoard.posts.post(
    connection,
    {
      body: {
        discussion_board_thread_id: thread_id,
        discussion_board_member_id: memberA.id,
        body: RandomGenerator.paragraph()(30),
      } satisfies IDiscussionBoardPost.ICreate,
    },
  );
  typia.assert(post);

  // Step 4: Member A files a report on their own post
  const reportA: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(
    connection,
    {
      body: {
        reporter_member_id: memberA.id,
        thread_id: null,
        post_id: post.id,
        comment_id: null,
        reason: "test: spam or abuse",
      } satisfies IDiscussionBoardReport.ICreate,
    },
  );
  typia.assert(reportA);

  // Step 5: Member A deletes (soft-deletes) their own report
  await api.functional.discussionBoard.reports.eraseById(
    connection,
    { id: reportA.id },
  );

  // Step 6: Attempt double-deletion (should trigger error)
  await TestValidator.error("double-deletion triggers conflict or error")(
    () => api.functional.discussionBoard.reports.eraseById(connection, { id: reportA.id }),
  );

  // Step 7: Attempt to delete a random non-existent report (should trigger error)
  await TestValidator.error("deleting non-existent report triggers not-found")(
    () => api.functional.discussionBoard.reports.eraseById(connection, { id: typia.random<string & tags.Format<"uuid">>() }),
  );

  // Step 8: Member B files a new report on the same post, deletes it as moderator
  const reportB: IDiscussionBoardReport = await api.functional.discussionBoard.reports.post(
    connection,
    {
      body: {
        reporter_member_id: memberB.id,
        thread_id: null,
        post_id: post.id,
        comment_id: null,
        reason: "test: duplicate content",
      } satisfies IDiscussionBoardReport.ICreate,
    },
  );
  typia.assert(reportB);
  // Moderator deletes their own report
  await api.functional.discussionBoard.reports.eraseById(
    connection,
    { id: reportB.id },
  );

  // Step 9: Attempt to delete B's report as unrelated user (Member A) — forbidden expected
  await TestValidator.error("non-owner cannot delete other's report")(
    () => api.functional.discussionBoard.reports.eraseById(connection, { id: reportB.id }),
  );
}
